properties.query:
// Detect Excel add-ins placed in XLSTART auto-start folders
let addinExtensions = dynamic([".xll", ".xla", ".xlam"]);
let lookback = 4h;
// Legitimate Microsoft Office add-ins to exclude
let legitimateAddins = dynamic([
  "analys32.xll",      // Analysis ToolPak
  "solver32.xll",      // Solver Add-in
  "atpvbaen.xla",      // Analysis ToolPak VBA
  "funcres.xlam",      // Function Library
  "procdb.xla",        // Spreadsheet Inquire
  "eurotool.xla",      // Euro Currency Tools
  "msquery.xla",       // Microsoft Query
  "xlquery.xla"        // Query and Pivot
]);
// Legitimate Office processes that can modify add-ins
let legitimateProcesses = dynamic([
  "officeclicktorun.exe",  // Office Click-to-Run updater
  "setup.exe",             // Office installer
  "msiexec.exe",          // Windows Installer
  "officebackgroundtaskhandler.exe", // Office background tasks
  "integrator.exe"         // Office integration service
]);
DeviceFileEvents
| where TimeGenerated > ago(lookback)
// Common creation/modification actions that indicate persistence attempts
| where ActionType in~ ('FileCreated', 'FileRenamed', 'FileRestored', 'FileModified')
// Normalize for robust matching
| extend FolderPath_l = tolower(FolderPath), FileName_l = tolower(FileName)
// XLSTART locations: per-user AppData and Program Files Office root (use has()/endswith to avoid backslash parsing in pipeline)
| where FolderPath_l endswith "xlstart"
    or (FolderPath_l has "microsoft" and FolderPath_l has "excel" and FolderPath_l has "xlstart")
    or (FolderPath_l has "program files" and FolderPath_l has "microsoft office" and FolderPath_l has "root" and FolderPath_l has "office")
// Only Excel add-in extensions
| where FileName_l endswith '.xll' or FileName_l endswith '.xla' or FileName_l endswith '.xlam'
// Exclude legitimate Microsoft Office add-ins
| where FileName_l !in (legitimateAddins)
// Exclude legitimate Office update/installation processes when run as SYSTEM
| where not(tolower(InitiatingProcessFileName) in (legitimateProcesses) and tolower(InitiatingProcessAccountName) == "system")
// Exclude Office update paths (contains GUIDs and update-specific folders)
| where not(FolderPath_l has "updates" and FolderPath_l has "download" and FolderPath_l has "packagefiles")
// Project useful context for incident triage & entity mappings
| project
    TimeGenerated,
    DeviceName,
    ActionType,
    FileName,
    FolderPath,
    InitiatingProcessFileName,
    InitiatingProcessAccountName

