// --- NPM Supply-Chain Attack (Sep 2025) IOC parameters ---
let PhishDomains = dynamic(["npmjs.help"]);
let PhishSenderAddresses = dynamic(["support@npmjs.help","support@npmjs[.]help"]);
let C2Domains = dynamic([
  "websocket-api2.publicvm.com",   // credential exfil (observed)
  "webhook.site"                   // exfil sink used by worm workflow
]);
let SuspiciousUrls = dynamic([
  "registry.npmjs.org/-/whoami",   // token validation by malware
  "metadata.google.internal",      // GCP metadata
  "169.254.169.254"                // AWS/Azure/GCP metadata IP
]);
let SuspiciousFileNames = dynamic(["bundle.js"]);
let SuspiciousRepoNames = dynamic(["Shai-Hulud"]);
let SuspiciousRepoSuffix = "-migration";
let SuspiciousProcs = dynamic(["trufflehog","node","node.exe","npm","pnpm","yarn","powershell.exe","pwsh.exe","bash","sh"]);
// Email with phishing domain in URLs
EmailUrlInfo
| where TimeGenerated > ago(14d)
| where UrlDomain has_any (PhishDomains)
| join kind=innerunique (
    EmailEvents
    | project NetworkMessageId, RecipientEmailAddress, SenderFromAddress, Subject, ThreatTypes, DeliveryAction
) on NetworkMessageId
| project TimeGenerated, RecipientEmailAddress, SenderFromAddress, Subject, ThreatTypes, DeliveryAction, Url, UrlDomain, NetworkMessageId

let High_Risk = (_GetWatchlist('High_Risk_Watchlist') | project SearchKey);
SecurityAlert
| where CompromisedEntity in (High_Risk) and IsIncident == "True"

